(78,'Raisin','🍇','Vigne grimpante cultivée pour ses fruits (raisin) ; lianescente.',NULL,'Vitis vinifera','Végétal (Chlorobiontes)','Angiosperme','Vitacées','Vitis',NULL,'Végétal (Chlorobiontes)','Angiosperme','Vitacées','Treille, plein soleil','terrestre',NULL,NULL,'Producteur primaire','producteur',0,'Vivace (liane)','vivace',NULL,NULL,NULL,NULL,NULL,'Fiche pédagogique ForêtMap',NULL,NULL,NULL,NULL,NULL,NULL,'Production primaire ; couvert grimpant',NULL,'Alimentation (fruit)',1,'Fruit (grappe)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
