INSERT INTO `glossary_terms` VALUES
('FM0001','écosystème','écosystèmes','ecosysteme','base','Ensemble formé par un milieu de vie et tous les êtres vivants qui y vivent et interagissent.','Un écosystème réunit un biotope (le milieu physique : sol, eau, lumière, climat) et une biocénose (l\'ensemble des êtres vivants). Les deux échangent en permanence matière et énergie. Le potager, la mare ou le bac d\'aquaponie de ForêtMap sont autant de petits écosystèmes.','Le bassin d\'aquaponie : eau, poissons, bactéries et plantes forment un écosystème.','Du grec oikos (maison) et systema (ensemble organisé).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0002','biodiversité','diversité biologique','ecologie','base','Variété de toutes les formes de vie : espèces, gènes et milieux.','La biodiversité se mesure à trois niveaux : la diversité des espèces, la diversité génétique au sein d\'une espèce, et la diversité des écosystèmes. Un jardin riche en espèces est plus résistant aux ravageurs et aux maladies.','Associer fleurs, légumes et auxiliaires augmente la biodiversité du potager.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0003','biotope',NULL,'ecosysteme','approfondissement','Milieu physique d\'un écosystème, avec ses conditions (sol, eau, lumière, température).','Le biotope, c\'est le « décor » non vivant : nature du sol, pH, humidité, ensoleillement, température. Il détermine quelles espèces peuvent s\'installer.','Un sol calcaire et sec est un biotope favorable au romarin et au thym.','Du grec bios (vie) et topos (lieu).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0004','biocénose',NULL,'ecosysteme','avance','Ensemble des êtres vivants d\'un même milieu et de leurs relations.','La biocénose regroupe toutes les populations (plantes, animaux, champignons, micro-organismes) qui cohabitent dans un biotope et tissent entre elles des relations alimentaires et de coopération.','Dans le compost : bactéries, champignons, vers et cloportes forment une biocénose.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0005','habitat',NULL,'ecologie','base','Lieu de vie d\'une espèce, qui lui fournit abri et ressources.','L\'habitat est l\'« adresse » d\'une espèce : l\'endroit où elle trouve nourriture, abri et conditions favorables pour se reproduire.','Le tas de bois mort est l\'habitat du cloporte et de nombreux insectes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0006','niche écologique','niche','ecologie','avance','Rôle et place d\'une espèce dans son écosystème (ce qu\'elle mange, où, quand).','La niche écologique est le « métier » d\'une espèce : ses ressources, ses prédateurs, son activité dans le temps et l\'espace. Deux espèces aux niches trop proches entrent en compétition.','L\'abeille et le bourdon partagent une niche proche : butiner le nectar des fleurs.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0007','espèce','espèces','taxonomie','base','Groupe d\'êtres vivants qui se ressemblent et peuvent se reproduire entre eux.','Une espèce regroupe des individus capables de se reproduire et de donner une descendance fertile. Chaque espèce porte un nom scientifique en deux mots (genre + espèce).','La tomate (Solanum lycopersicum) et l\'aubergine (Solanum melongena) sont deux espèces du même genre.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0008','population','populations','ecologie','approfondissement','Ensemble des individus d\'une même espèce vivant au même endroit.','Une population, c\'est tous les individus d\'une espèce présents dans un même milieu à un moment donné. Sa taille varie selon les naissances, les morts et les déplacements.','La population de pucerons explose au printemps si aucun prédateur ne la régule.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0010','chaîne alimentaire','chaîne trophique','ecologie','base','Suite d\'êtres vivants où chacun mange le précédent.','Une chaîne alimentaire relie les êtres vivants par « qui mange qui ». Elle commence toujours par un producteur (une plante), suivi de consommateurs, et se termine par les décomposeurs.','Feuille de chou → chenille de piéride → araignée argiope.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0011','réseau trophique','réseau alimentaire','ecologie','approfondissement','Ensemble des chaînes alimentaires reliées entre elles dans un écosystème.','Dans la réalité, les chaînes alimentaires s\'entremêlent : une espèce a souvent plusieurs proies et plusieurs prédateurs. Le réseau trophique de ForêtMap relie les espèces par pollinisation, herbivorie, prédation, décomposition et nitrification.','Le réseau trophique du potager relie plantes, pollinisateurs, ravageurs et auxiliaires.','De trophê (nourriture, en grec).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0012','niveau trophique',NULL,'ecologie','avance','Position d\'un être vivant dans la chaîne alimentaire (producteur, consommateur, décomposeur).','Chaque maillon occupe un niveau trophique. À chaque niveau, une grande partie de l\'énergie est perdue : c\'est pourquoi les chaînes dépassent rarement 4 ou 5 maillons.','Producteur (1er niveau) → herbivore (2e) → carnivore (3e).',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0013','producteur','producteur primaire, autotrophe','ecologie','base','Être vivant qui fabrique sa propre matière à partir de lumière (les plantes).','Les producteurs sont les plantes et les algues : grâce à la photosynthèse, ils fabriquent leur matière organique à partir d\'eau, de dioxyde de carbone et de lumière. Ils sont à la base de toutes les chaînes alimentaires.','La laitue, le maïs et l\'élodée sont des producteurs.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0014','consommateur','consommateurs','ecologie','base','Être vivant qui se nourrit d\'autres êtres vivants.','Les consommateurs ne savent pas fabriquer leur matière : ils mangent d\'autres organismes. On distingue les herbivores (mangeurs de plantes), les carnivores (mangeurs d\'animaux) et les omnivores.','Le puceron (herbivore) et l\'argiope (carnivore) sont des consommateurs.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0015','décomposeur','décomposeurs','ecologie','base','Être vivant qui recycle la matière organique morte en éléments minéraux.','Les décomposeurs (bactéries, champignons) et les détritivores (vers, cloportes) transforment les feuilles mortes, les déchets et les cadavres en humus et en sels minéraux réutilisables par les plantes. Ils bouclent le cycle de la matière.','Le ver de lombricompost et le cloporte décomposent les déchets du compost.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0016','autotrophe','autotrophes','ecologie','avance','Organisme qui fabrique sa matière organique à partir de matière minérale.','Un autotrophe se nourrit « par lui-même » : les plantes par photosynthèse, certaines bactéries par chimiosynthèse (comme les bactéries nitrifiantes). Ils n\'ont pas besoin de manger d\'autres êtres vivants.','Les plantes vertes et les bactéries Nitrosomonas sont autotrophes.','Du grec autos (soi-même) et trophê (nourriture).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0017','hétérotrophe','hétérotrophes','ecologie','avance','Organisme qui doit consommer de la matière organique d\'autres êtres vivants.','Les hétérotrophes ne savent pas fabriquer leur matière : animaux, champignons et la plupart des bactéries doivent se nourrir d\'autres organismes.','Tous les animaux du jardin sont hétérotrophes.','Du grec heteros (autre) et trophê (nourriture).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0018','photosynthèse',NULL,'flore','base','Fabrication de matière organique par les plantes à partir de lumière, d\'eau et de CO2.','Dans leurs feuilles, grâce à la chlorophylle, les plantes captent la lumière pour transformer l\'eau et le dioxyde de carbone en sucres, en rejetant du dioxygène. C\'est la réaction qui nourrit presque toute la vie sur Terre.','Une feuille au soleil produit des sucres et libère de l\'oxygène.','Du grec phôs (lumière) et synthesis (assemblage).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0019','matière organique',NULL,'sol','approfondissement','Matière issue du vivant (débris végétaux, animaux, déjections).','La matière organique du sol provient des êtres vivants morts et de leurs déchets. Décomposée, elle forme l\'humus qui nourrit les plantes et nourrit la vie du sol.','Les feuilles mortes et le fumier apportent de la matière organique au compost.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0020','cycle de l\'azote',NULL,'ecosysteme','approfondissement','Parcours de l\'azote entre l\'air, le sol, l\'eau et les êtres vivants.','L\'azote circule en boucle : les déchets azotés (ammonium) sont transformés par des bactéries en nitrites puis en nitrates, que les plantes absorbent pour fabriquer leurs protéines. C\'est le cœur du fonctionnement de l\'aquaponie et du sol vivant.','En aquaponie : déjections des poissons → ammonium → nitrites → nitrates → plantes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0021','nitrification',NULL,'ecosysteme','avance','Transformation de l\'ammonium en nitrates par des bactéries, en deux étapes.','La nitrification se fait en deux temps : Nitrosomonas oxyde l\'ammonium (NH4+) en nitrites (NO2-), puis Nitrobacter et Nitrospira oxydent les nitrites en nitrates (NO3-), assimilables par les plantes. Ces bactéries sont le filtre vivant de l\'aquaponie.','Sans bactéries nitrifiantes, l\'ammoniac des poissons resterait toxique.','Du latin nitrum (salpêtre, composé azoté).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0022','ammonium','ammoniac, NH4','ecosysteme','avance','Forme azotée issue des déchets des animaux, toxique à forte dose.','L\'ammonium (NH4+) et l\'ammoniac (NH3) proviennent des déjections et de la décomposition des protéines. Dans l\'eau d\'un aquarium ou d\'un bac d\'aquaponie, ils deviennent vite toxiques s\'ils ne sont pas transformés par les bactéries.','Les déjections du tilapia libèrent de l\'ammonium dans l\'eau.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0023','nitrate','nitrates, NO3','ecosysteme','approfondissement','Forme azotée assimilable par les plantes, produit final de la nitrification.','Les nitrates (NO3-) sont la principale source d\'azote des plantes. En aquaponie, ils ferment le cycle : ce qui était un déchet toxique devient l\'engrais des plantes, qui épurent l\'eau en retour.','Les racines de l\'élodée absorbent les nitrates et nettoient l\'eau.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0024','bactérie nitrifiante','bactéries nitrifiantes','faune','avance','Bactérie qui transforme l\'azote des déchets en nitrates utilisables.','Ces bactéries autotrophes (Nitrosomonas, Nitrobacter, Nitrospira) tirent leur énergie de l\'oxydation des composés azotés. Invisibles à l\'œil nu, elles colonisent les supports du biofiltre et rendent l\'aquaponie possible.','Nitrosomonas, Nitrobacter et Nitrospira assurent la nitrification.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0025','fixation de l\'azote','fixation symbiotique','ecosysteme','avance','Capacité de certaines bactéries à transformer l\'azote de l\'air en azote utilisable.','L\'azote de l\'air (N2) est inutilisable par les plantes. Des bactéries (Rhizobium) logées dans les racines des légumineuses le fixent et le transforment en composés azotés. C\'est pourquoi les légumineuses enrichissent le sol.','Le haricot, la fève et le petit pois fixent l\'azote grâce à leurs nodosités.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0026','aquaponie',NULL,'eau_aquaponie','base','Élevage de poissons couplé à la culture de plantes, dans une eau recyclée.','L\'aquaponie associe trois acteurs : des poissons qui produisent des déchets azotés, des bactéries qui les transforment, et des plantes qui absorbent les nitrates en épurant l\'eau. C\'est un écosystème en boucle quasi fermée.','Le bac d\'aquaponie de ForêtMap relie tilapias, bactéries et plantes aquatiques.','De aqua (eau) et (hydro)ponie (culture hors-sol).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0027','biofiltre','filtre biologique','eau_aquaponie','approfondissement','Support où vivent les bactéries qui épurent l\'eau.','Le biofiltre offre une grande surface où les bactéries nitrifiantes se fixent et transforment l\'ammonium en nitrates. C\'est le « rein » du système aquaponique.','Sans biofiltre colonisé, un système d\'aquaponie neuf n\'épure pas l\'eau.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0028','pH',NULL,'methode_svt','base','Mesure de l\'acidité ou de la basicité d\'un sol ou d\'une eau (de 0 à 14).','Le pH indique si un milieu est acide (moins de 7), neutre (7) ou basique (plus de 7). Chaque plante a une plage de pH préférée ; en aquaponie, un pH proche de la neutralité satisfait à la fois poissons, bactéries et plantes.','La plupart des légumes préfèrent un sol au pH de 6,0 à 7,0.','De l\'allemand « potenz Hydrogen » (puissance de l\'hydrogène).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0030','sol vivant',NULL,'sol','base','Sol riche en êtres vivants qui le rendent fertile.','Un sol vivant grouille de bactéries, champignons, vers et insectes qui décomposent la matière organique, aèrent la terre et libèrent les éléments nutritifs. Le nourrir, c\'est nourrir les plantes indirectement.','Le paillage et le compost entretiennent un sol vivant.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0031','humus',NULL,'sol','approfondissement','Matière organique décomposée qui donne au sol sa fertilité et sa couleur sombre.','L\'humus est le produit stable de la décomposition. Il retient l\'eau et les nutriments, et libère lentement les éléments dont les plantes ont besoin.','Un compost mûr ressemble à un terreau noir : c\'est de l\'humus.','Mot latin signifiant « terre, sol ».',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0032','compostage','compost','agroecologie','base','Transformation des déchets organiques en engrais naturel par les décomposeurs.','Le compostage rassemble des déchets verts (épluchures, tontes) et bruns (feuilles, carton) que bactéries, champignons et invertébrés décomposent en quelques mois, donnant un amendement riche pour le jardin.','On composte les épluchures de cuisine pour fertiliser le potager.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0033','lombricompostage','vermicompostage, lombricompost','agroecologie','approfondissement','Compostage des déchets grâce à des vers spécialisés.','Le lombricompostage utilise des vers (comme Eisenia fetida) qui digèrent les déchets organiques et produisent un compost très riche (le lombricompost) et un engrais liquide.','Le lombricomposteur transforme les épluchures grâce au ver de lombricompost.','Du latin lumbricus (ver de terre).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0034','décomposition',NULL,'ecologie','base','Dégradation de la matière morte en éléments simples réutilisables.','La décomposition est l\'étape qui ferme le cycle de la matière : les décomposeurs et détritivores transforment les organismes morts en minéraux que les plantes réutilisent.','Les feuilles mortes se décomposent et nourrissent le sol.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0035','détritivore','détritivores','faune','approfondissement','Animal qui se nourrit de débris organiques (feuilles mortes, déchets).','Les détritivores (vers de terre, cloportes) fragmentent la matière morte et la rendent accessible aux bactéries et champignons décomposeurs. Ils sont les premiers maillons du recyclage.','Le cloporte et le ver de terre sont des détritivores du compost.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0036','paillage','mulch','agroecologie','base','Couche de matière qui protège et nourrit le sol.','Le paillage couvre le sol de paille, feuilles ou broyat. Il limite l\'évaporation, freine les herbes spontanées et nourrit la vie du sol en se décomposant.','Pailler les tomates réduit les arrosages.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0040','pollinisation',NULL,'interaction','base','Transport du pollen d\'une fleur à une autre, qui permet la formation des fruits.','La pollinisation transfère le pollen des étamines vers le pistil. Réalisée par des insectes (entomogamie) ou le vent (anémogamie), elle est indispensable à la production de la plupart des fruits et graines.','L\'abeille pollinise la fleur de courgette en butinant.','Du latin pollen (poussière fine).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0041','pollinisateur','pollinisateurs','interaction','base','Animal qui transporte le pollen entre les fleurs.','Les pollinisateurs (abeilles, bourdons, papillons, certains coléoptères) butinent le nectar et transportent le pollen d\'une fleur à l\'autre. Leur disparition menace directement nos récoltes.','L\'abeille est le pollinisateur le plus connu du jardin.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0042','herbivorie',NULL,'interaction','approfondissement','Relation où un animal se nourrit de plantes.','L\'herbivorie relie un consommateur à une plante dont il mange les feuilles, la sève ou les racines. Modérée, elle fait partie de l\'équilibre ; excessive, elle devient un dégât de ravageur.','Le puceron pratique l\'herbivorie en piquant la sève des tomates.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0043','prédation',NULL,'interaction','base','Relation où un animal (prédateur) tue et mange un autre (proie).','La prédation régule naturellement les populations. Au jardin, les prédateurs d\'insectes sont de précieux alliés contre les ravageurs.','L\'argiope capture la piéride dans sa toile : c\'est de la prédation.','Du latin praeda (proie).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0044','symbiose','mutualisme','interaction','approfondissement','Association durable entre deux espèces dont chacune tire profit.','Dans une symbiose mutualiste, les deux partenaires y gagnent. L\'exemple clé du jardin : les bactéries Rhizobium et les légumineuses, ou les champignons mycorhiziens et les racines.','La fève et les bactéries fixatrices d\'azote vivent en symbiose.','Du grec sun (avec) et bios (vie).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0045','parasitisme',NULL,'interaction','approfondissement','Relation où une espèce (parasite) vit aux dépens d\'une autre (hôte).','Le parasite se nourrit de son hôte sans le tuer immédiatement, ce qui l\'affaiblit. Beaucoup de ravageurs ont eux-mêmes des parasites qui en font des auxiliaires.','Certaines guêpes parasitent les chenilles en y pondant leurs œufs.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0046','compétition',NULL,'interaction','approfondissement','Relation où des êtres vivants se disputent une même ressource.','La compétition oppose des individus pour la lumière, l\'eau, les nutriments ou l\'espace. Elle existe entre espèces différentes ou au sein d\'une même espèce.','Les « mauvaises herbes » entrent en compétition avec les légumes pour l\'eau et la lumière.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0047','plante-hôte','plante hôte','interaction','approfondissement','Plante sur laquelle une espèce se nourrit ou se développe.','Une plante-hôte abrite une partie du cycle de vie d\'un animal, souvent ses larves. La connaître permet d\'anticiper les ravageurs… ou d\'attirer des espèces utiles.','Le chou est la plante-hôte des chenilles de la piéride.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0048','auxiliaire','auxiliaires, insecte auxiliaire','interaction','base','Animal utile au jardinier, qui régule les ravageurs ou pollinise.','Les auxiliaires rendent service au jardin : prédateurs de ravageurs (coccinelles, araignées, mantes), pollinisateurs (abeilles) ou décomposeurs (vers). Les favoriser réduit le besoin de traitements.','L\'argiope et la mante religieuse sont des auxiliaires prédateurs.','Du latin auxilium (aide).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0049','ravageur','ravageurs, nuisible','interaction','base','Organisme qui cause des dégâts aux cultures.','Un ravageur consomme ou abîme les plantes cultivées au point de réduire la récolte. La lutte biologique cherche à le contrôler par ses ennemis naturels plutôt que par des produits chimiques.','Le puceron, la cochenille et la piéride sont des ravageurs courants.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0050','lutte biologique','biocontrôle','agroecologie','approfondissement','Contrôle des ravageurs par leurs ennemis naturels plutôt que par des pesticides.','La lutte biologique utilise prédateurs, parasites ou maladies naturelles pour limiter les ravageurs. Elle préserve l\'équilibre de l\'écosystème et la biodiversité.','Favoriser les coccinelles et les araignées limite les pucerons sans pesticide.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0060','agroécologie',NULL,'agroecologie','approfondissement','Façon de cultiver qui s\'appuie sur les équilibres naturels des écosystèmes.','L\'agroécologie cherche à produire en imitant la nature : sols vivants, biodiversité, associations de plantes, recyclage de la matière, peu d\'intrants. C\'est la philosophie de fond de ForêtMap.','Composter, associer les cultures et favoriser les auxiliaires relèvent de l\'agroécologie.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0061','permaculture',NULL,'agroecologie','approfondissement','Méthode de conception de cultures durables inspirée des écosystèmes naturels.','La permaculture conçoit des jardins productifs et autonomes en observant la nature : étager les plantes, recycler, coopérer plutôt que lutter contre le milieu.','La forêt comestible est une application de la permaculture.','De l\'anglais permanent agriculture.',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0062','forêt comestible','jardin-forêt','agroecologie','base','Jardin organisé comme une forêt, avec plusieurs étages de plantes utiles.','La forêt comestible superpose des strates (arbres fruitiers, arbustes, herbacées, couvre-sols, grimpantes) pour créer un écosystème productif, autonome et riche en biodiversité.','Grenadier, framboisier et fraisier peuvent cohabiter dans une forêt comestible.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0063','association de plantes','compagnonnage, cultures associées','agroecologie','base','Culture côte à côte de plantes qui s\'entraident.','Certaines plantes se rendent service : l\'une repousse un ravageur, l\'autre attire un pollinisateur ou enrichit le sol. Bien associées, elles poussent mieux et tombent moins malades.','La milpa associe maïs, haricot grimpant et courge.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0064','semence','semences, graine, graines','flore','base','Graine destinée à être semée pour donner une nouvelle plante.','La semence contient l\'embryon de la future plante et ses réserves. Conserver et ressemer ses graines (semences paysannes) préserve la diversité cultivée.','On récolte les semences de tomate pour les ressemer l\'année suivante.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0065','germination',NULL,'cycle_de_vie','base','Sortie de la jeune plante hors de la graine.','Avec de l\'eau, de la chaleur et de l\'oxygène, la graine se réveille : la radicule puis la tige sortent. C\'est le début du cycle de vie de la plante.','Un radis germe en quelques jours seulement.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0066','floraison',NULL,'cycle_de_vie','base','Période où la plante produit ses fleurs.','La floraison permet la reproduction : les fleurs attirent les pollinisateurs, puis se transforment en fruits et graines après pollinisation.','La floraison du courgette précède la formation des fruits.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0070','plante annuelle','annuelle','cycle_de_vie','base','Plante qui accomplit tout son cycle de vie en une seule année.','Une annuelle germe, fleurit, produit ses graines puis meurt en une saison. Il faut la ressemer chaque année.','La laitue, le radis et le maïs sont des plantes annuelles.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0071','plante bisannuelle','bisannuelle','cycle_de_vie','approfondissement','Plante dont le cycle de vie s\'étale sur deux ans.','La première année, la bisannuelle fait ses feuilles et ses réserves ; la deuxième année, elle fleurit, graine puis meurt.','La carotte et le chou sont des bisannuelles.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0072','plante vivace','vivace, plante pérenne','cycle_de_vie','base','Plante qui vit plusieurs années.','Une vivace repousse chaque année à partir de ses racines, de sa souche ou de son tronc. Elle structure durablement le jardin.','Le romarin, la menthe et le framboisier sont des vivaces.','De vivax (qui a la vie tenace, en latin).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0073','angiosperme','angiospermes, plante à fleurs','flore','avance','Plante à fleurs dont les graines sont enfermées dans un fruit.','Les angiospermes sont le groupe de plantes le plus répandu : elles font des fleurs, et leurs graines mûrissent à l\'intérieur d\'un fruit. Presque tous les légumes et fruits du jardin en font partie.','La tomate est une angiosperme : sa graine est dans le fruit.','Du grec aggeion (récipient) et sperma (graine).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0080','taxonomie','classification, systématique','taxonomie','approfondissement','Science qui nomme et classe les êtres vivants.','La taxonomie range le vivant en groupes emboîtés : règne, embranchement, classe, ordre, famille, genre, espèce. Elle permet de parler de la même espèce partout dans le monde.','La tomate : règne Végétal, famille Solanacées, genre Solanum, espèce lycopersicum.','Du grec taxis (ordre) et nomos (loi).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0081','règne','règnes','taxonomie','base','Plus grand groupe de classification des êtres vivants.','Le règne est le premier niveau de tri du vivant. ForêtMap distingue trois règnes : Végétal, Animal et Bactérie.','L\'abeille appartient au règne Animal, la menthe au règne Végétal.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0082','famille','familles','taxonomie','approfondissement','Groupe de classification rassemblant des genres proches.','La famille regroupe des espèces qui partagent des caractères communs. Connaître la famille d\'un légume aide à prévoir ses besoins, ses maladies et ses associations.','Tomate, poivron et aubergine appartiennent à la famille des Solanacées.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0083','genre','genres','taxonomie','approfondissement','Groupe de classification rassemblant des espèces très proches.','Le genre est le premier mot du nom scientifique. Les espèces d\'un même genre se ressemblent beaucoup.','Allium est le genre de l\'oignon, de l\'ail et de la ciboulette.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0084','nom scientifique','nom binominal, binôme latin','taxonomie','approfondissement','Nom universel d\'une espèce, en deux mots latins (genre + espèce).','Chaque espèce a un nom scientifique unique, en latin, compris partout dans le monde, ce qui évite les confusions entre noms communs locaux.','« Tomate » se dit partout Solanum lycopersicum.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0085','bioindicateur','bio-indicateur, indicateur biologique','methode_svt','avance','Espèce dont la présence renseigne sur l\'état d\'un milieu.','La présence ou l\'absence de certaines espèces signale la qualité d\'un sol, d\'une eau ou de l\'air. Observer les bioindicateurs est une méthode de suivi écologique.','Les vers de terre nombreux sont un bon bioindicateur d\'un sol sain.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0100','être vivant','êtres vivants','ecologie','base','Ce qui naît, se nourrit, grandit, se reproduit et meurt.','Un être vivant respire, se nourrit, grandit et donne naissance à des descendants. On le distingue du non-vivant (l\'eau, une pierre, l\'air).','Une plante, un insecte et une bactérie sont des êtres vivants.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0101','micro-organisme','micro-organismes, microbe','faune','base','Être vivant trop petit pour être vu à l\'œil nu.','Les micro-organismes (bactéries, champignons microscopiques) sont partout : dans le sol, l\'eau et l\'air. Beaucoup sont utiles, comme ceux qui font le compost ou épurent l\'eau de l\'aquaponie.','Les bactéries du biofiltre sont des micro-organismes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0102','bactérie','bactéries','faune','base','Micro-organisme formé d\'une seule cellule.','Les bactéries sont les plus petits êtres vivants. Certaines décomposent les déchets, d\'autres transforment l\'azote ; sans elles, le sol et l\'aquaponie ne fonctionneraient pas.','Nitrosomonas est une bactérie qui transforme l\'azote.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0103','champignon','champignons','faune','base','Être vivant qui se nourrit de matière organique, ni animal ni plante.','Les champignons forment un règne à part. Dans le sol, des champignons microscopiques décomposent la matière morte et aident les racines à se nourrir.','La moisissure sur un fruit oublié est un champignon.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0104','insecte','insectes','faune','base','Petit animal à six pattes et au corps en trois parties.','Les insectes ont 6 pattes, souvent des ailes, et un corps en trois parties (tête, thorax, abdomen). C\'est le groupe d\'animaux le plus nombreux du jardin.','L\'abeille, le puceron et la piéride sont des insectes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0105','arthropode','arthropodes','faune','approfondissement','Animal au corps articulé et à carapace, sans squelette interne.','Les arthropodes ont un squelette externe (carapace) et des pattes articulées. Ils regroupent les insectes, les araignées et les crustacés comme le cloporte.','Insectes, araignées et cloportes sont des arthropodes.','Du grec arthron (articulation) et podos (pied).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0106','mollusque','mollusques','faune','base','Animal au corps mou, souvent protégé par une coquille.','Les mollusques ont un corps mou ; beaucoup portent une coquille. Au jardin et dans la mare, on trouve les escargots et les limaces.','La planorbe et la limnée sont des mollusques aquatiques.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0107','vertébré','vertébrés','faune','base','Animal qui possède une colonne vertébrale (un squelette interne).','Les vertébrés ont un squelette à l\'intérieur du corps, avec une colonne vertébrale. Ce sont les poissons, les amphibiens, les reptiles, les oiseaux et les mammifères.','Le tilapia et le chat sont des vertébrés.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0108','invertébré','invertébrés','faune','base','Animal qui n\'a pas de colonne vertébrale.','Les invertébrés n\'ont pas de squelette interne. Ils représentent la grande majorité des animaux : insectes, vers, araignées, escargots.','Le ver de terre et l\'abeille sont des invertébrés.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0109','mammifère','mammifères','faune','base','Animal qui allaite ses petits et possède des poils.','Les mammifères nourrissent leurs petits avec du lait et ont généralement des poils. L\'humain en fait partie.','Le chat est un mammifère.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0110','ver','vers','faune','base','Animal au corps mou et allongé, sans pattes.','Les vers de terre creusent des galeries qui aèrent le sol et avalent la terre en la rendant plus fertile. Ce sont de précieux alliés du jardinier.','Le ver de terre et le ver de lombricompost vivent dans le sol.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0111','araignée','araignées, arachnide','faune','base','Animal à huit pattes qui tisse souvent une toile.','Les araignées ont 8 pattes (ce ne sont pas des insectes). Beaucoup capturent des insectes nuisibles : ce sont des auxiliaires du jardin.','L\'argiope tisse une toile pour capturer ses proies.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0112','racine','racines','flore','base','Partie de la plante qui pousse dans le sol.','Les racines fixent la plante et absorbent l\'eau et les sels minéraux du sol. Certaines, comme la carotte, servent de réserve.','On mange la racine de la carotte et du radis.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0113','tige','tiges','flore','base','Partie de la plante qui porte les feuilles et les fleurs.','La tige relie les racines aux feuilles et transporte la sève. Elle dresse la plante vers la lumière.','La tige du maïs peut dépasser deux mètres.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0114','feuille','feuilles','flore','base','Organe vert de la plante où se fait la photosynthèse.','C\'est dans les feuilles, grâce à la chlorophylle, que la plante capte la lumière pour fabriquer sa nourriture et rejeter de l\'oxygène.','On récolte les feuilles de la laitue et du basilic.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0115','fleur','fleurs','flore','base','Organe de reproduction de la plante, souvent coloré.','La fleur attire les pollinisateurs ; une fois pollinisée, elle se transforme en fruit contenant les graines.','La fleur de courgette devient une courgette après pollinisation.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0116','fruit','fruits','flore','base','Organe qui se forme après la fleur et protège les graines.','Le fruit se développe à partir de la fleur fécondée et renferme les graines. En cuisine, on appelle « légumes » certains fruits comme la tomate.','La tomate et le concombre sont des fruits au sens botanique.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0117','graine','graines','flore','base','Organe qui contient l\'embryon d\'une nouvelle plante.','La graine renferme une jeune plante en réserve. Semée dans de bonnes conditions, elle germe et donne une nouvelle plante.','Une graine de haricot germe en quelques jours.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0118','bourgeon','bourgeons','flore','approfondissement','Petite pousse d\'où sortiront des feuilles ou des fleurs.','Le bourgeon est une réserve de croissance protégée par des écailles. Au printemps, il s\'ouvre pour donner feuilles, tiges ou fleurs.','Les bourgeons du framboisier débourrent au printemps.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0119','sève',NULL,'flore','approfondissement','Liquide qui circule dans la plante pour la nourrir.','La sève transporte l\'eau et les sels minéraux des racines vers les feuilles, et les sucres fabriqués vers le reste de la plante.','Le puceron pique la tige pour aspirer la sève.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0120','chlorophylle',NULL,'flore','approfondissement','Pigment vert des plantes qui capte la lumière.','La chlorophylle donne leur couleur verte aux feuilles et permet la photosynthèse en captant l\'énergie de la lumière.','C\'est la chlorophylle qui rend les feuilles vertes.','Du grec khloros (vert) et phullon (feuille).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0121','nectar',NULL,'flore','base','Liquide sucré produit par les fleurs pour attirer les pollinisateurs.','Le nectar récompense les insectes qui viennent butiner ; en se déplaçant de fleur en fleur, ils transportent le pollen.','L\'abeille récolte le nectar pour fabriquer le miel.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0122','pollen',NULL,'flore','base','Fine poudre des fleurs qui permet la reproduction des plantes.','Le pollen contient les cellules mâles de la plante. Transporté sur une autre fleur, il permet la formation des graines.','L\'abeille se couvre de pollen en butinant.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0123','étamine','étamines','flore','approfondissement','Organe mâle de la fleur qui produit le pollen.','Les étamines portent le pollen à l\'extrémité de petits filaments, au cœur de la fleur.','Les étamines de la tomate libèrent leur pollen avec les vibrations.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0124','pistil',NULL,'flore','approfondissement','Organe femelle de la fleur qui reçoit le pollen.','Le pistil, au centre de la fleur, capte le pollen ; c\'est là que se forment les graines après la fécondation.','Le pollen doit atteindre le pistil pour former un fruit.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0126','reproduction',NULL,'cycle_de_vie','base','Façon dont les êtres vivants donnent naissance à des descendants.','La reproduction assure la survie de l\'espèce. Chez les plantes, elle passe souvent par les fleurs et les graines ; chez les animaux, par les œufs ou les petits.','La fleur permet la reproduction de la plante.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0127','cycle de vie','cycle de développement','cycle_de_vie','base','Suite des étapes de la vie d\'un être vivant, de la naissance à la reproduction.','Le cycle de vie décrit toutes les étapes : graine → plante → fleur → graine, ou œuf → larve → adulte. Il se répète de génération en génération.','Le cycle de la piéride : œuf → chenille → chrysalide → papillon.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0128','croissance',NULL,'cycle_de_vie','base','Augmentation de la taille d\'un être vivant.','Pour grandir, un être vivant a besoin de nourriture, d\'eau et de bonnes conditions. Une plante grandit grâce à la lumière, l\'eau et les sels minéraux.','La croissance du maïs est très rapide en été.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0129','métamorphose','métamorphoses','cycle_de_vie','base','Grande transformation du corps d\'un animal au cours de sa vie.','Certains animaux changent complètement de forme en grandissant. La chenille devient papillon : c\'est une métamorphose.','La chenille de la piéride se métamorphose en papillon.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0130','larve','larves','cycle_de_vie','base','Jeune animal très différent de l\'adulte, avant la métamorphose.','La larve est une étape du développement de nombreux animaux. Elle ne ressemble pas encore à l\'adulte et n\'a souvent pas le même régime alimentaire.','La chenille est la larve du papillon.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0131','chenille','chenilles','faune','base','Larve de papillon, au corps allongé, qui mange beaucoup de feuilles.','La chenille passe son temps à manger des feuilles pour grandir avant de se transformer en papillon. Certaines sont des ravageurs du potager.','La chenille de la piéride dévore les feuilles de chou.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0132','ponte','œuf, œufs','cycle_de_vie','base','Dépôt des œufs par un animal femelle.','Beaucoup d\'animaux pondent des œufs d\'où sortiront les jeunes. La femelle choisit souvent un endroit qui nourrira ses larves.','La piéride pond ses œufs sous les feuilles de chou.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0133','bouture','boutures, bouturage','agroecologie','approfondissement','Morceau de plante qui forme des racines et donne une nouvelle plante.','Le bouturage multiplie une plante sans graine : on plante un fragment de tige qui développe ses propres racines.','On multiplie facilement la menthe par bouture.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0134','semis',NULL,'agroecologie','base','Action de semer des graines pour faire pousser des plantes.','Le semis consiste à mettre des graines en terre ou en godet. Avec de l\'eau et de la chaleur, elles germent et donnent de jeunes plants.','On démarre les semis de tomate au printemps.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0135','repiquage','repiquer','agroecologie','approfondissement','Replanter un jeune plant à un nouvel endroit pour lui donner de la place.','Quand les jeunes plants issus du semis sont assez forts, on les repique plus espacés pour qu\'ils se développent mieux.','On repique les plants de salade quand ils ont quelques feuilles.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0136','herbivore','herbivores','interaction','base','Animal qui se nourrit de plantes.','Les herbivores mangent des feuilles, des tiges, des fruits ou de la sève. Au potager, certains deviennent des ravageurs.','Le puceron et la chenille sont des herbivores.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0137','carnivore','carnivores','interaction','base','Animal qui se nourrit d\'autres animaux.','Les carnivores chassent ou capturent des proies. Au jardin, ils régulent les populations de ravageurs.','L\'argiope et la mante religieuse sont carnivores.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0138','omnivore','omnivores','interaction','base','Animal qui mange à la fois des plantes et des animaux.','Les omnivores ont un régime varié. Beaucoup de poissons et l\'humain sont omnivores.','Le tilapia est omnivore : algues, plantes et petits animaux.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0139','prédateur','prédateurs','interaction','base','Animal qui chasse, tue et mange d\'autres animaux.','Le prédateur capture une proie pour se nourrir. Les prédateurs d\'insectes sont de précieux auxiliaires.','La mante religieuse est un prédateur d\'insectes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0140','proie','proies','interaction','base','Animal chassé et mangé par un prédateur.','La proie est la victime du prédateur. Pour survivre, beaucoup de proies se camouflent ou se reproduisent en grand nombre.','Le puceron est une proie pour l\'argiope.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0141','régime alimentaire','alimentation','interaction','approfondissement','Ensemble de ce qu\'un animal mange habituellement.','Le régime alimentaire classe les animaux en herbivores, carnivores, omnivores ou décomposeurs. Il détermine leur place dans la chaîne alimentaire.','Le régime du puceron est strictement herbivore.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0142','sol',NULL,'sol','base','Couche de terre où poussent les plantes.','Le sol est un mélange de particules minérales (argile, sable), d\'eau, d\'air et de matière organique. Un bon sol abrite une vie intense.','Lire son sol aide à savoir quoi y cultiver.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0143','texture du sol','argile, sable, limon','sol','approfondissement','Proportion d\'argile, de sable et de limon dans un sol.','La texture décide si un sol retient l\'eau (argile) ou si elle s\'écoule vite (sable). Elle guide le choix des cultures et des arrosages.','Un sol sableux se draine vite et chauffe au soleil.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0144','terreau',NULL,'sol','base','Terre riche et légère préparée pour les cultures.','Le terreau est un mélange riche en matière organique, idéal pour les semis et le rempotage.','On remplit les godets de terreau pour les semis.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0145','engrais',NULL,'agroecologie','base','Matière qui apporte aux plantes les éléments dont elles ont besoin.','Les engrais fournissent surtout de l\'azote, du phosphore et du potassium. Le compost est un engrais naturel ; les engrais chimiques, mal dosés, peuvent polluer.','Le compost mûr est un excellent engrais naturel.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0146','sels minéraux','minéraux','sol','approfondissement','Éléments du sol dont les plantes ont besoin pour grandir.','Dissous dans l\'eau, les sels minéraux (azote, phosphore, potassium…) sont absorbés par les racines. Les décomposeurs en libèrent en recyclant la matière morte.','Les racines puisent les sels minéraux dans l\'eau du sol.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0147','dioxyde de carbone','CO2, gaz carbonique','methode_svt','approfondissement','Gaz utilisé par les plantes pour la photosynthèse.','Les plantes absorbent le dioxyde de carbone de l\'air pour fabriquer leurs sucres et rejettent du dioxygène. Les êtres vivants en rejettent en respirant.','La feuille capte le CO2 de l\'air le jour.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0148','dioxygène','oxygène, O2','methode_svt','approfondissement','Gaz indispensable à la respiration des êtres vivants.','Le dioxygène est produit par les plantes lors de la photosynthèse. Tous les êtres vivants en ont besoin pour respirer, y compris les poissons dans l\'eau.','Les plantes aquatiques oxygènent l\'eau du bassin.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0149','respiration',NULL,'methode_svt','base','Échange de gaz par lequel les êtres vivants utilisent le dioxygène.','En respirant, les êtres vivants absorbent du dioxygène et rejettent du dioxyde de carbone. Plantes et animaux respirent, jour et nuit.','Les poissons respirent l\'oxygène dissous dans l\'eau.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0150','arrosage','arroser','agroecologie','base','Apport d\'eau aux plantes cultivées.','Bien arroser, c\'est donner la bonne quantité au bon moment, de préférence le matin ou le soir pour limiter l\'évaporation.','On arrose au pied des plants pour économiser l\'eau.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0151','drainage','drainer','sol','approfondissement','Écoulement de l\'eau en excès hors du sol.','Un bon drainage évite que les racines pourrissent dans l\'eau stagnante. Les sols sableux drainent vite, les argileux retiennent l\'eau.','Des billes d\'argile au fond du pot améliorent le drainage.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0152','érosion',NULL,'sol','approfondissement','Usure et entraînement du sol par l\'eau ou le vent.','Un sol nu s\'érode : la pluie emporte la bonne terre. Le couvert végétal et le paillage protègent le sol de l\'érosion.','Couvrir le sol limite l\'érosion par la pluie.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0153','potager',NULL,'agroecologie','base','Jardin où l\'on cultive des légumes et des herbes.','Le potager produit des légumes, des aromatiques et parfois des fruits. Bien organisé, il accueille aussi des fleurs et des auxiliaires.','Le potager de ForêtMap regroupe tomates, salades et aromatiques.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0154','verger',NULL,'agroecologie','base','Terrain planté d\'arbres fruitiers.','Le verger réunit des arbres et arbustes qui donnent des fruits. Leurs fleurs nourrissent aussi les pollinisateurs au printemps.','Prunier et grenadier ont leur place au verger.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0155','serre','serres','agroecologie','approfondissement','Abri vitré qui garde la chaleur pour protéger les cultures.','La serre capte la chaleur du soleil et protège du froid, ce qui permet de cultiver plus tôt ou des plantes frileuses.','On démarre les semis sous serre au printemps.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0156','récolte','récolter, moisson','agroecologie','base','Cueillette des parties de la plante que l\'on consomme.','On récolte au bon moment selon la plante : feuilles, fruits, racines ou graines. Récolter régulièrement encourage souvent de nouvelles productions.','On récolte les laitues avant qu\'elles ne montent en fleur.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0157','plante aromatique','aromatique, aromatiques, fines herbes','flore','base','Plante au parfum marqué, utilisée pour parfumer les plats.','Les aromatiques dégagent des odeurs qui parfument la cuisine et repoussent parfois certains ravageurs. Beaucoup sont des vivaces faciles à cultiver.','Basilic, menthe, romarin et thym sont des aromatiques.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0158','légume','légumes','flore','base','Plante potagère ou partie de plante que l\'on mange.','Selon la plante, le légume est une feuille (salade), une racine (carotte), un fruit (tomate) ou une graine (petit pois).','La carotte est un légume-racine, l\'épinard un légume-feuille.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0159','rotation des cultures','assolement','agroecologie','approfondissement','Changer l\'emplacement des cultures d\'une année sur l\'autre.','La rotation évite d\'épuiser le sol et limite les maladies en ne replantant pas la même famille au même endroit chaque année.','Après les légumes gourmands, on sème des légumineuses qui enrichissent le sol.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0160','désherbage','désherber','agroecologie','base','Enlever les herbes spontanées qui concurrencent les cultures.','Le désherbage doux (à la main, par paillage) limite les plantes indésirables sans produits chimiques et préserve la vie du sol.','Le paillage réduit le désherbage au potager.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0161','compost mûr','amendement','agroecologie','base','Compost décomposé, prêt à nourrir le sol.','Après plusieurs mois, le compost devient sombre et friable comme du terreau : il est mûr et peut être étalé au pied des cultures.','On étale le compost mûr à l\'automne.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0162','recyclage','recycler','agroecologie','base','Réutiliser une matière au lieu de la jeter.','Au jardin, recycler c\'est transformer les déchets verts en compost et l\'eau de pluie en arrosage. La nature recycle tout grâce aux décomposeurs.','Le compostage recycle les épluchures en engrais.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0163','déchet organique','déchets verts, biodéchet','agroecologie','base','Déchet issu du vivant, qui peut être composté.','Épluchures, feuilles mortes, tontes : les déchets organiques se décomposent et nourrissent le sol au lieu de finir à la poubelle.','Les épluchures sont des déchets organiques compostables.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0164','environnement',NULL,'ecologie','base','Tout ce qui entoure un être vivant et l\'influence.','L\'environnement comprend le milieu physique (air, eau, sol, climat) et les autres êtres vivants. Le protéger, c\'est préserver les conditions de la vie.','Jardiner sans pesticide protège l\'environnement.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0165','pollution','polluer, polluant','ecologie','base','Dégradation du milieu par des substances nuisibles.','La pollution de l\'eau, de l\'air ou du sol nuit aux êtres vivants. Au jardin, l\'excès d\'engrais et de pesticides est une source de pollution.','Trop d\'engrais pollue l\'eau des rivières.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0166','pesticide','pesticides','ecologie','approfondissement','Produit utilisé pour tuer les ravageurs ou les herbes indésirables.','Les pesticides éliminent des nuisibles mais touchent aussi les auxiliaires et polluent. L\'agroécologie cherche à s\'en passer grâce à la lutte biologique.','Les pesticides peuvent tuer les abeilles.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0167','développement durable',NULL,'ecologie','approfondissement','Répondre à nos besoins sans abîmer la planète pour l\'avenir.','Le développement durable cherche l\'équilibre entre les besoins humains, le respect de la nature et le partage des ressources, aujourd\'hui et pour les générations futures.','Composter et économiser l\'eau participent au développement durable.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0168','ressource naturelle','ressources','ecologie','approfondissement','Élément de la nature utile aux êtres vivants (eau, sol, lumière).','L\'eau, le sol fertile, la lumière et les nutriments sont des ressources. Certaines se renouvellent, d\'autres s\'épuisent si on les surexploite.','L\'eau de pluie est une ressource précieuse au jardin.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0169','adaptation','adapter, adaptations','ecologie','approfondissement','Caractère qui aide un être vivant à survivre dans son milieu.','Au fil du temps, les espèces développent des adaptations : épines du cactus contre la sécheresse, camouflage du phasme contre les prédateurs.','Les épines du cactus sont une adaptation à la sécheresse.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0170','camouflage','mimétisme','interaction','base','Capacité d\'un animal à se confondre avec son environnement.','Le camouflage aide à échapper aux prédateurs ou à surprendre une proie. Certains animaux imitent une brindille ou une feuille.','Le phasme imite une brindille : c\'est du camouflage.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0171','biodiversité du sol','vie du sol','sol','approfondissement','Ensemble des êtres vivants qui peuplent le sol.','Bactéries, champignons, vers, cloportes et insectes du sol travaillent ensemble à le rendre fertile. Un sol vivant est un sol plein de biodiversité.','Une poignée de terre de jardin abrite des milliers d\'organismes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0200','flux d\'énergie','flux énergétique','ecosysteme','avance','Circulation de l\'énergie dans un écosystème, des producteurs aux consommateurs.','L\'énergie entre par la lumière captée par les producteurs, puis passe de maillon en maillon. À chaque transfert, une grande partie est perdue sous forme de chaleur : l\'énergie circule à sens unique et ne se recycle pas, contrairement à la matière.','Seule une fraction de l\'énergie d\'une plante se retrouve dans l\'herbivore qui la mange.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0201','production primaire','productivité primaire','ecosysteme','avance','Quantité de matière organique fabriquée par les producteurs.','La production primaire mesure la matière organique créée par photosynthèse sur une surface et une durée données. Elle constitue la base énergétique de tout l\'écosystème.','Une mare riche en élodées a une forte production primaire.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0202','biomasse',NULL,'ecosysteme','avance','Masse totale de matière vivante présente dans un milieu.','La biomasse est la quantité de matière organique des êtres vivants, exprimée par unité de surface ou de volume. Elle diminue fortement quand on monte dans les niveaux trophiques.','La biomasse des plantes dépasse de loin celle des herbivores.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0203','pyramide écologique','pyramide des biomasses, pyramide trophique','ecosysteme','avance','Représentation des niveaux trophiques selon leur nombre, biomasse ou énergie.','Empilés, les niveaux trophiques forment une pyramide : beaucoup de producteurs à la base, peu de prédateurs au sommet, car l\'énergie disponible diminue à chaque étage.','La pyramide des biomasses du potager : énormément de plantes, peu d\'araignées.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0204','rendement écologique','efficacité de transfert','ecosysteme','avance','Part de l\'énergie transmise d\'un niveau trophique au suivant (environ 10 %).','À chaque maillon, seuls ~10 % de l\'énergie passent au niveau supérieur ; le reste est perdu (respiration, chaleur, parties non consommées). C\'est pourquoi les chaînes alimentaires sont courtes.','Sur 100 unités d\'énergie d\'une plante, ~10 atteignent l\'herbivore.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0205','cycle biogéochimique',NULL,'ecosysteme','avance','Circulation en boucle d\'un élément chimique entre vivant et milieu.','Contrairement à l\'énergie, la matière se recycle : carbone, azote, eau et minéraux passent sans cesse des êtres vivants au sol, à l\'eau et à l\'air, puis reviennent.','Le cycle de l\'azote et le cycle du carbone sont des cycles biogéochimiques.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0206','cycle du carbone',NULL,'ecosysteme','avance','Circulation du carbone entre l\'atmosphère, les êtres vivants et le sol.','Les plantes fixent le carbone du CO2 par photosynthèse ; la respiration et la décomposition le rendent à l\'atmosphère. Le compostage et les sols vivants stockent du carbone.','Composter renvoie au sol du carbone plutôt que de le brûler.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0207','minéralisation',NULL,'sol','avance','Transformation de la matière organique en éléments minéraux par les décomposeurs.','En fin de décomposition, micro-organismes et détritivores libèrent des sels minéraux (azote, phosphore…) assimilables par les plantes. C\'est l\'étape qui « rend » les nutriments au sol.','La minéralisation libère l\'azote des feuilles mortes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0208','humification',NULL,'sol','avance','Formation de l\'humus à partir de la matière organique décomposée.','Avant d\'être minéralisée, une partie de la matière organique se transforme en humus stable, qui retient eau et nutriments et structure le sol.','Un compost bien conduit favorise l\'humification.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0209','respiration cellulaire',NULL,'methode_svt','avance','Réaction qui libère l\'énergie des sucres en consommant du dioxygène.','Dans les cellules, les sucres sont dégradés avec du dioxygène pour produire de l\'énergie utilisable, en rejetant du CO2 et de l\'eau. Tous les êtres vivants respirent, y compris les plantes.','La nuit, la plante respire sans faire de photosynthèse.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0210','ATP','adénosine triphosphate','methode_svt','avance','Molécule qui stocke et fournit l\'énergie aux cellules.','L\'ATP est la « monnaie énergétique » de la cellule : produite par la respiration, elle alimente toutes les activités du vivant.','La respiration cellulaire fabrique de l\'ATP utilisable par la cellule.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0211','cellule','cellules','methode_svt','avance','Plus petite unité vivante qui constitue tous les êtres vivants.','Tous les organismes sont faits de cellules : une seule chez les bactéries, des milliards chez une plante ou un animal. La cellule réalise les fonctions de la vie.','Une bactérie nitrifiante est formée d\'une seule cellule.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0212','chloroplaste','chloroplastes','flore','avance','Élément de la cellule végétale où se déroule la photosynthèse.','Les chloroplastes contiennent la chlorophylle et captent la lumière pour fabriquer des sucres. On ne les trouve que dans les cellules vertes des végétaux et de certaines algues.','Les chloroplastes des feuilles donnent leur couleur verte.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0214','fermentation',NULL,'methode_svt','avance','Dégradation de la matière organique sans dioxygène par des micro-organismes.','En l\'absence d\'oxygène, certaines bactéries et levures dégradent la matière organique et libèrent de l\'énergie. Mal gérée, elle rend un compost malodorant.','Un compost tassé et gorgé d\'eau fermente et sent mauvais.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0215','ammonification',NULL,'ecosysteme','avance','Libération d\'ammonium à partir de la matière organique azotée.','Première étape du recyclage de l\'azote : les décomposeurs transforment les protéines des déchets et cadavres en ammonium, point de départ de la nitrification.','Les bactéries du sol ammonifient les protéines des feuilles mortes.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0216','dénitrification',NULL,'ecosysteme','avance','Transformation des nitrates en azote gazeux par des bactéries, en l\'absence d\'oxygène.','Dans les milieux peu oxygénés, certaines bactéries renvoient l\'azote des nitrates vers l\'atmosphère sous forme de gaz. C\'est l\'étape qui « ferme » le cycle de l\'azote.','Un sol gorgé d\'eau favorise la dénitrification.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0217','nodosité','nodosités','ecosysteme','avance','Renflement des racines de légumineuses abritant des bactéries fixatrices d\'azote.','Les bactéries Rhizobium logées dans les nodosités fixent l\'azote de l\'air et le partagent avec la plante, qui les nourrit en sucres : une symbiose qui enrichit le sol.','Les racines de fève portent des nodosités roses actives.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0218','assimilation de l\'azote',NULL,'ecosysteme','avance','Absorption des nitrates par les plantes pour fabriquer leurs protéines.','Les plantes prélèvent les nitrates par leurs racines et les utilisent pour construire leurs protéines et leur ADN. C\'est l\'étape qui fait entrer l\'azote dans la chaîne alimentaire.','Les racines de l\'élodée assimilent les nitrates de l\'eau.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0219','complexe argilo-humique',NULL,'sol','avance','Assemblage d\'argile et d\'humus qui retient l\'eau et les nutriments du sol.','Argiles et humus s\'associent pour former une structure qui stocke l\'eau et les sels minéraux et les libère lentement aux plantes : c\'est la clé de la fertilité d\'un sol.','Un sol riche en complexe argilo-humique reste fertile longtemps.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0220','mycorhize','mycorhizes','sol','avance','Association entre un champignon et les racines d\'une plante.','Le champignon étend le réseau d\'absorption de la plante (eau, phosphore) et reçoit des sucres en échange. Cette symbiose très répandue améliore la nutrition des plantes.','La plupart des arbres du verger vivent en mycorhize.','Du grec mukês (champignon) et rhiza (racine).',NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0221','rhizosphère',NULL,'sol','avance','Zone du sol au contact des racines, très riche en micro-organismes.','Autour des racines, les exsudats nourrissent une intense vie microbienne qui aide la plante à se nourrir et la protège. C\'est un point chaud de la vie du sol.','La rhizosphère grouille de bactéries utiles aux racines.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0223','dynamique des populations',NULL,'ecologie','avance','Étude des variations du nombre d\'individus d\'une population dans le temps.','Naissances, morts, arrivées et départs font varier une population. Prédateurs, ressources et climat la régulent ; un déséquilibre peut provoquer une pullulation de ravageurs.','Sans prédateurs, la population de pucerons explose au printemps.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0224','capacité de charge','capacité limite','ecologie','avance','Nombre maximal d\'individus qu\'un milieu peut nourrir durablement.','Chaque milieu a des ressources limitées : au-delà d\'un certain effectif, la population ne peut plus croître et se stabilise ou s\'effondre.','Un bassin d\'aquaponie a une capacité de charge limitée en poissons.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0225','facteur limitant',NULL,'ecologie','avance','Élément dont le manque freine le développement d\'un être vivant.','La croissance est bornée par la ressource la plus rare : lumière, eau, azote, espace… Identifier le facteur limitant permet d\'agir efficacement.','En intérieur, la lumière est souvent le facteur limitant des semis.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0226','facteur abiotique','facteurs abiotiques','ecologie','avance','Élément non vivant qui influence les êtres vivants (lumière, eau, température, pH).','Les facteurs abiotiques décrivent les conditions physiques et chimiques du milieu. Ils déterminent quelles espèces peuvent s\'y installer.','Température et pH sont des facteurs abiotiques clés en aquaponie.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0227','facteur biotique','facteurs biotiques','ecologie','avance','Influence exercée par les êtres vivants les uns sur les autres.','Prédation, compétition, pollinisation, maladies : les facteurs biotiques sont toutes les actions du vivant sur le vivant.','La présence de prédateurs est un facteur biotique qui régule les pucerons.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0228','succession écologique',NULL,'ecosysteme','avance','Évolution naturelle d\'un milieu et de son peuplement au fil du temps.','Un sol nu se couvre d\'abord d\'herbes pionnières, puis d\'arbustes et d\'arbres : la communauté se transforme progressivement vers un état plus stable.','Une parcelle abandonnée évolue vers la friche puis le bois.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0229','résilience','résilience écologique','ecosysteme','avance','Capacité d\'un écosystème à se remettre d\'une perturbation.','Un écosystème riche et diversifié résiste mieux aux aléas (sécheresse, ravageurs) et retrouve plus vite son équilibre : la biodiversité renforce la résilience.','Un potager diversifié est plus résilient face aux ravageurs.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0230','espèce clé de voûte',NULL,'ecologie','avance','Espèce dont le rôle est essentiel à l\'équilibre de tout l\'écosystème.','Sa disparition bouleverse l\'ensemble de la communauté, bien au-delà de son effectif. Les pollinisateurs jouent ce rôle dans beaucoup de milieux.','L\'abeille agit comme une espèce clé de voûte pour la pollinisation.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0231','espèce ingénieure','ingénieur de l\'écosystème','ecologie','avance','Espèce qui modifie physiquement son milieu et le rend habitable pour d\'autres.','En transformant le milieu, elle crée des conditions favorables à d\'autres espèces. Le ver de terre, en creusant et brassant le sol, en est l\'exemple emblématique.','Le ver de terre est une espèce ingénieure du sol.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0232','espèce invasive','espèce exotique envahissante, EEE','conservation','avance','Espèce introduite qui prolifère au détriment des espèces locales.','Introduite hors de son aire d\'origine, elle se multiplie sans régulation et menace la biodiversité locale. Certaines introductions « utiles » ont mal tourné.','La gambusie, introduite contre les moustiques, est devenue invasive ailleurs.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0235','commensalisme',NULL,'interaction','avance','Relation où une espèce profite d\'une autre sans lui nuire ni l\'aider.','Le commensal tire avantage de la relation (abri, transport, restes de nourriture) tandis que l\'autre n\'est ni gêné ni avantagé.','Certains insectes vivent dans les galeries du ver de terre sans le gêner.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0236','allélopathie',NULL,'interaction','avance','Influence chimique d\'une plante sur la croissance d\'une autre.','Certaines plantes libèrent des substances qui freinent ou favorisent leurs voisines. On en tient compte dans les associations de cultures.','Certaines plantes inhibent la germination de leurs voisines par allélopathie.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0237','coévolution',NULL,'interaction','avance','Évolution conjointe de deux espèces qui s\'influencent mutuellement.','Au fil des générations, deux espèces en relation étroite s\'adaptent l\'une à l\'autre, comme les fleurs et leurs pollinisateurs.','Fleurs et abeilles ont coévolué : forme des fleurs et comportement des butineuses.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0238','sélection naturelle',NULL,'ecologie','avance','Mécanisme par lequel les individus les mieux adaptés survivent et se reproduisent davantage.','Dans un milieu donné, les individus porteurs de caractères avantageux laissent plus de descendants : la sélection naturelle est le moteur de l\'évolution décrit par Darwin.','Les pucerons résistants à un traitement sont sélectionnés et se multiplient.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0239','évolution','évolution biologique','ecologie','avance','Transformation des espèces au cours des générations.','Sous l\'effet de la variabilité génétique et de la sélection naturelle, les espèces changent au fil du temps et de nouvelles apparaissent. C\'est l\'histoire du vivant.','La diversité des choux cultivés illustre l\'évolution guidée par l\'humain.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0241','diversité génétique','variabilité génétique','ecologie','avance','Variété des gènes au sein d\'une même espèce.','Plus une population est génétiquement variée, mieux elle résiste aux maladies et s\'adapte aux changements. Conserver des variétés anciennes préserve cette diversité.','Ressemer des semences paysannes maintient la diversité génétique.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0242','domestication',NULL,'agroecologie','avance','Sélection par l\'humain d\'espèces sauvages pour les cultiver ou les élever.','Au fil des siècles, l\'humain a sélectionné les plantes et animaux les plus utiles, transformant des espèces sauvages en variétés cultivées.','Le chou, le brocoli et le chou-fleur viennent d\'une même espèce domestiquée.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0243','eutrophisation',NULL,'eau_aquaponie','avance','Enrichissement excessif d\'une eau en nutriments, qui asphyxie le milieu.','Un excès de nitrates et de phosphates provoque une prolifération d\'algues ; en se décomposant, elles consomment l\'oxygène et étouffent la vie aquatique.','Un excès d\'engrais lessivé vers une mare provoque son eutrophisation.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0244','cycle de l\'eau','cycle hydrologique','ecosysteme','avance','Circulation continue de l\'eau entre la terre, l\'océan et l\'atmosphère.','L\'eau s\'évapore, forme des nuages, retombe en pluie, ruisselle et s\'infiltre, puis s\'évapore à nouveau. Les plantes y participent par la transpiration.','Récupérer l\'eau de pluie s\'inscrit dans le cycle de l\'eau.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0245','lessivage',NULL,'sol','avance','Entraînement des éléments solubles du sol par l\'eau en profondeur.','Une pluie abondante sur un sol nu emporte les nitrates et minéraux hors de portée des racines, vers les nappes : une perte de fertilité et une source de pollution.','Le lessivage des nitrates pollue les nappes phréatiques.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33'),
('FM0246','chimioautotrophie','chimiosynthèse','faune','avance','Fabrication de matière organique à partir d\'énergie chimique, sans lumière.','Certaines bactéries tirent leur énergie de réactions chimiques (et non de la lumière) pour fabriquer leur matière. Les bactéries nitrifiantes de l\'aquaponie en sont l\'exemple parfait.','Nitrosomonas est chimioautotrophe : elle se nourrit en oxydant l\'ammonium.',NULL,NULL,'actif','2026-06-16 19:37:33','2026-06-16 19:37:33');
